          output.push(opStack.pop()!);
        }
        if (opStack.length > 0 && ['sin', 'cos', 'tan', 'asin', 'acos', 'atan', 'ln', 'log', 'sqrt'].includes(opStack[opStack.length - 1])) {
          output.push(opStack.pop()!);
        }
      }
    }
    while (opStack.length > 0) {
      const top = opStack.pop()!;
      if (top !== '(' && top !== ')') {
        output.push(top);
      }
    }

    return output.map(t => {
      if (t === 'u-') return '-';
      if (t === 'u+') return '+';
      return t;
    }).join(' ');
  } catch {
    return '';
  }
}

