                    break
            op_stack.append(token)
        elif token == '(':
            op_stack.append(token)
        elif token == ')':
            matched = False
            while op_stack:
                top = op_stack[-1]
                if top == '(':
                    op_stack.pop()
                    matched = True
                    break
                output.append(op_stack.pop())
            if not matched:
                raise ValueError("Unexpected token ')'")
        else:
            raise ValueError(f"Unknown token '{token}'")

    while op_stack:
        top = op_stack.pop()
        if top in ('(', ')'):
            raise ValueError("Expected ')' but reached end of expression")
        output.append(top)

    return output

def evaluate_postfix(tokens: list[str], angle_unit: str = "radians") -> Decimal:
    stack = []

    constants = {
        'pi': Decimal('3.141592653589793238462643383'),
        'e': Decimal('2.718281828459045235360287471')
    }

    functions = {'sin', 'cos', 'tan', 'asin', 'acos', 'atan', 'ln', 'log', 'sqrt'}
    binary_operators = {'+', '-', '*', '/', '^'}
    unary_operators = {'u-', 'u+'}

    for token in tokens:
        if token in constants:
            stack.append(constants[token])
        elif token in unary_operators:
            if not stack:
                raise ValueError(f"Insufficient operands on the stack for operator '{token}'")
            arg = stack.pop()
            if token == 'u-':
                stack.append(-arg)
            else:
                stack.append(arg)
        elif token in functions:
            if not stack:
                raise ValueError(f"Insufficient operands on the stack for function '{token}'")
            arg = stack.pop()
            res = evaluate_function_impl(token, arg, angle_unit)
            stack.append(res)
        elif token in binary_operators:
            if len(stack) < 2:
                raise ValueError(f"Insufficient operands on the stack for operator '{token}'")
            right = stack.pop()
            left = stack.pop()
            res = evaluate_binary_impl(left, token, right)
            stack.append(res)
        else:
            # Must be a number
            try:
                stack.append(Decimal(token))
            except InvalidOperation:
                raise ValueError(f"Expected number, constant, function, or operator but found '{token}'")

    if len(stack) != 1:
        if len(stack) == 0:
            raise ValueError("Expression is empty or evaluation resulted in empty stack")
        raise ValueError(f"Unexpected values on stack. Unresolved tokens remain: {len(stack)} items")

    return stack[0]

def evaluate_function_impl(func_name: str, arg: Decimal, angle_unit: str) -> Decimal:
    val = float(arg)

    try:
        if func_name == 'sqrt':
            if arg < 0:
                raise ValueError("Square root of negative number is not allowed")
            return arg.sqrt()

        elif func_name == 'ln':
            if arg <= 0:
                raise ValueError("Logarithm of non-positive number is not allowed")
            return arg.ln()

        elif func_name == 'log':
            if arg <= 0:
                raise ValueError("Logarithm of non-positive number is not allowed")
            return arg.log10()

        elif func_name == 'sin':
            if angle_unit == 'degrees':
                val = math.radians(val)
            res = math.sin(val)
            if abs(res) < 1e-15:
                res = 0.0
            return Decimal(str(res))

        elif func_name == 'cos':
            if angle_unit == 'degrees':
                val = math.radians(val)
            res = math.cos(val)
            if abs(res) < 1e-15:
                res = 0.0
            return Decimal(str(res))

        elif func_name == 'tan':
            if angle_unit == 'degrees':
                if abs((val - 90) % 180) < 1e-9:
                    raise ZeroDivisionError("Tangent is undefined for this angle")
                val = math.radians(val)
            else:
                if abs((val - math.pi / 2) % math.pi) < 1e-9:
                    raise ZeroDivisionError("Tangent is undefined for this angle")
            res = math.tan(val)
            if abs(res) < 1e-15:
                res = 0.0
            return Decimal(str(res))

        elif func_name == 'asin':
            if not (-1.0 <= val <= 1.0):
                raise ValueError("asin input must be between -1 and 1")
            res = math.asin(val)
            if angle_unit == 'degrees':
                res = math.degrees(res)
            return Decimal(str(res))

        elif func_name == 'acos':
            if not (-1.0 <= val <= 1.0):
                raise ValueError("acos input must be between -1 and 1")
            res = math.acos(val)
            if angle_unit == 'degrees':
                res = math.degrees(res)
            return Decimal(str(res))

        elif func_name == 'atan':
            res = math.atan(val)
            if angle_unit == 'degrees':
                res = math.degrees(res)
            return Decimal(str(res))

        else:
            raise ValueError(f"Unknown function '{func_name}'")

    except ZeroDivisionError as e:
        raise e
    except ValueError as e:
        raise e
    except Exception as e:
        raise ValueError(f"Math error in {func_name}: {str(e)}")

def evaluate_binary_impl(left: Decimal, op: str, right: Decimal) -> Decimal:
    if op == '+':
        return left + right
    elif op == '-':
        return left - right
    elif op == '*':
        return left * right
    elif op == '/':
        if right == Decimal('0'):
            raise ZeroDivisionError("Division by zero")
        return left / right
    elif op == '^':
        try:
            if right % 1 != 0:
                if left < 0:
                    raise ValueError("Negative number raised to a fractional power is not allowed")
                res = float(left) ** float(right)
                if math.isnan(res) or math.isinf(res):
                    raise ValueError("Result of exponentiation is undefined or too large")
                return Decimal(str(res))
            else:
                return left ** int(right)
        except (OverflowError, Overflow):
            raise ValueError("Result of exponentiation is too large (Overflow)")
        except (InvalidOperation, ValueError, ZeroDivisionError) as e:
            if "Negative number" in str(e):
                raise e
            raise ValueError("Invalid power operation")
    else:
        raise ValueError(f"Unknown operator '{op}'")

def evaluate_expression(expression: str, angle_unit: str = "radians", mode: str = "infix") -> Decimal:
    """
    Parses and evaluates the provided standard (infix) or postfix (RPN) expression with high precision.
    """
    angle_unit = angle_unit.lower()
    mode = mode.lower()

    if mode == "postfix":
        if not expression.strip():
            raise ValueError("Expression is empty")
        tokens = expression.strip().split()
        return evaluate_postfix(tokens, angle_unit)

    elif mode == "infix":
        tokens = tokenize_infix(expression)
        postfix_tokens = infix_to_postfix(tokens)
        return evaluate_postfix(postfix_tokens, angle_unit)

    else:
        raise ValueError(f"Invalid mode '{mode}'. Must be 'infix' or 'postfix'")

from fastapi import FastAPI, HTTPException, status
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel, Field
from typing import Literal
from decimal import Decimal
from app.calculator import evaluate_expression

app = FastAPI(
    title="High-Precision Web Calculator API",
    description="A robust, PEMDAS-compliant arithmetic and scientific calculation backend with Shunting-Yard and Stack RPN engine",
    version="2.0.0"
)

# Configure CORS to allow frontend connection
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],  # In production, specify the exact origin(s)
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

class EvaluateRequest(BaseModel):
    operation: str = Field(..., description="The arithmetic/scientific expression or space-separated postfix string to evaluate")
    angle_unit: Literal["radians", "degrees"] = Field("radians", description="The angle unit for trigonometric functions")
    mode: Literal["infix", "postfix"] = Field("infix", description="The math evaluation mode (infix standard or postfix RPN)")

class EvaluateResponse(BaseModel):
    result: float = Field(..., description="The numeric result of the evaluation")

@app.post(
    "/api/v1/evaluate",
    response_model=EvaluateResponse,
    status_code=status.HTTP_200_OK,
    summary="Evaluate an arithmetic or scientific expression"
)
async def evaluate(request: EvaluateRequest):
    expression = request.operation
    angle_unit = request.angle_unit
    mode = request.mode

    try:
        decimal_result = evaluate_expression(expression, angle_unit, mode)

        # Check for non-finite values (Infinity/NaN)
        if decimal_result.is_infinite() or decimal_result.is_nan():
            raise HTTPException(
                status_code=status.HTTP_400_BAD_REQUEST,
                detail={
                    "type": "math error",
                    "message": "Calculation resulted in an undefined or out-of-range value"
                }
            )

        # Convert Decimal to float for JSON response serialization
        return EvaluateResponse(result=float(decimal_result))

    except ZeroDivisionError as e:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail={
                "type": "math error",
                "message": "Division by zero is not allowed"
            }
        )
    except ValueError as e:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail={
                "type": "syntax error",
                "message": str(e)
            }
        )
    except Exception as e:
        raise HTTPException(
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
            detail={
                "type": "server error",
                "message": f"An unexpected system error occurred: {str(e)}"
            }
        )

