def evaluate_binary_impl(left: Decimal, op: str, right: Decimal) -> Decimal:
    if op == '+':
        return left + right
    elif op == '-':
        return left - right
    elif op == '*':
        return left * right
    elif op == '/':
        if right == Decimal('0'):
            raise ZeroDivisionError("Division by zero")
        return left / right
    elif op == '^':
        try:
            if right % 1 != 0:
                if left < 0:
