// Client-side Infix to Postfix converter for live preview
function getPostfixPreview(infix: string): string {
  if (!infix.trim()) return '';
  try {
    const tokens: string[] = [];
    const pattern = /(\d*\.?\d+)|([a-zA-Z_][a-zA-Z0-9_]*)|([+\-*/()^])|(\s+)/g;
